    for (int j = 0; j < n; j++) {
        for (int k = 0; k <= j; k++) {
            res[i++] = mat[j][k];
        }
    }
    for (int j = n - 1; j >= 0; j--) {
        for (int k = n - 1; k > j; k--) {
            res[i++] = mat[j][k];
        }
    }
    return res;
}

