  dp[1] = 1;
  int i2 = 1, i3 = 1, i5 = 1;
  for (int i = 2; i <= n; i++) {
    int next = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
    if (next == dp[i2] * 2) i2++;
    if (next == dp[i3] * 3) i3++;
    if (next == dp[i5] * 5) i5++;
    dp[i] = next;
  }
  return dp[n];
}

